//! Minimal HTTP/1.1 request reader and response writer: one request per
//! connection.

use std::fmt::Write as _;
use std::io::{self, Read, Write};

const HEADER_END: &[u8] = b"\r\n\r\n";
const CRLF: &[u8] = b"\r\n";
const CHUNK_SIZE: usize = 16 * 1024;

#[derive(Debug)]
pub struct Request {
    pub method: String,
    pub target: String,
    pub body: Vec<u8>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StatusCode {
    Ok = 200,
    Created = 201,
    NoContent = 204,
    BadRequest = 400,
    NotFound = 404,
    MethodNotAllowed = 405,
    ContentTooLarge = 413,
    RequestHeaderFieldsTooLarge = 431,
    InternalServerError = 500,
    NotImplemented = 501,
    HttpVersionNotSupported = 505,
}

impl StatusCode {
    pub fn code(self) -> u16 {
        self as u16
    }

    pub fn reason(self) -> &'static str {
        match self {
            Self::Ok => "OK",
            Self::Created => "Created",
            Self::NoContent => "No Content",
            Self::BadRequest => "Bad Request",
            Self::NotFound => "Not Found",
            Self::MethodNotAllowed => "Method Not Allowed",
            Self::ContentTooLarge => "Content Too Large",
            Self::RequestHeaderFieldsTooLarge => "Request Header Fields Too Large",
            Self::InternalServerError => "Internal Server Error",
            Self::NotImplemented => "Not Implemented",
            Self::HttpVersionNotSupported => "HTTP Version Not Supported",
        }
    }
}

/// Response body: either owned bytes or a shared stored value (sent without
/// copying).
#[derive(Debug, Clone)]
pub enum Body {
    Empty,
    Owned(Vec<u8>),
    Shared(std::sync::Arc<[u8]>),
}

impl Body {
    fn as_bytes(&self) -> &[u8] {
        match self {
            Self::Empty => &[],
            Self::Owned(v) => v,
            Self::Shared(v) => v,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Response {
    pub status: StatusCode,
    pub headers: Vec<(&'static str, String)>,
    pub body: Body,
}

impl Response {
    pub fn empty(status: StatusCode) -> Self {
        Self {
            status,
            headers: Vec::new(),
            body: Body::Empty,
        }
    }

    pub fn with_body(status: StatusCode, body: Body, content_type: &str) -> Self {
        Self {
            status,
            headers: vec![("Content-Type", content_type.to_owned())],
            body,
        }
    }

    pub fn text(status: StatusCode, body: impl Into<Vec<u8>>) -> Self {
        Self::with_body(
            status,
            Body::Owned(body.into()),
            "text/plain; charset=utf-8",
        )
    }

    pub fn header(mut self, name: &'static str, value: impl Into<String>) -> Self {
        self.headers.push((name, value.into()));
        self
    }

    /// Writes the full response.
    pub fn write_to(&self, w: &mut impl Write) -> io::Result<()> {
        let body = self.body.as_bytes();
        let mut head = format!(
            "HTTP/1.1 {} {}\r\n",
            self.status.code(),
            self.status.reason()
        );
        for (name, value) in &self.headers {
            head.push_str(name);
            head.push_str(": ");
            head.push_str(value);
            head.push_str("\r\n");
        }
        if self.status != StatusCode::NoContent {
            // Writing into a String cannot fail.
            let _ = write!(head, "Content-Length: {}\r\n", body.len());
        }
        head.push_str("Connection: close\r\n\r\n");

        w.write_all(head.as_bytes())?;
        w.write_all(body)?;
        w.flush()
    }
}

/// Limits applied while reading a request.
#[derive(Debug, Clone, Copy)]
pub struct Limits {
    pub max_header_bytes: usize,
    pub max_body_bytes: usize,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            max_header_bytes: 64 * 1024,
            max_body_bytes: 1024 * 1024,
        }
    }
}

/// Outcome of reading one request from a connection.
#[derive(Debug)]
pub enum ReadOutcome {
    Request(Request),
    /// The request was malformed; send this response instead.
    Reject(Response),
    /// The peer closed, timed out, or failed before a full request arrived.
    Disconnected,
}

fn reject(status: StatusCode) -> ReadOutcome {
    ReadOutcome::Reject(Response::empty(status))
}

fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack.windows(needle.len()).position(|w| w == needle)
}

fn trim(s: &[u8]) -> &[u8] {
    let is_ws = |b: &u8| *b == b' ' || *b == b'\t';
    let start = s.iter().position(|b| !is_ws(b)).unwrap_or(s.len());
    let end = s.iter().rposition(|b| !is_ws(b)).map_or(start, |i| i + 1);
    &s[start..end]
}

/// Parses a Content-Length value: ASCII digits only, no sign, no overflow.
fn parse_content_length(value: &[u8]) -> Option<usize> {
    if value.is_empty() || !value.iter().all(u8::is_ascii_digit) {
        return None;
    }
    std::str::from_utf8(value).ok()?.parse().ok()
}

/// Reads and discards `remaining` bytes so the peer sees a clean close rather
/// than a reset when we reply without consuming its body.
fn discard(r: &mut impl Read, remaining: usize) {
    // Errors just mean the peer is gone; nothing more to do.
    let _ = io::copy(&mut r.take(remaining as u64), &mut io::sink());
}

/// Reads exactly one request from `r`.
pub fn read_request(r: &mut impl Read, limits: &Limits) -> ReadOutcome {
    let mut buf = Vec::new();
    let mut chunk = vec![0u8; CHUNK_SIZE];

    let header_end = loop {
        if buf.len() > limits.max_header_bytes {
            return reject(StatusCode::RequestHeaderFieldsTooLarge);
        }
        let n = match r.read(&mut chunk) {
            Ok(0) | Err(_) => return ReadOutcome::Disconnected,
            Ok(n) => n,
        };
        let search_from = buf.len().saturating_sub(HEADER_END.len() - 1);
        buf.extend_from_slice(&chunk[..n]);
        if let Some(pos) = find(&buf[search_from..], HEADER_END) {
            break search_from + pos;
        }
    };
    if header_end > limits.max_header_bytes {
        return reject(StatusCode::RequestHeaderFieldsTooLarge);
    }

    let head = &buf[..header_end];
    let (request_line, mut rest) = match find(head, CRLF) {
        Some(i) => (&head[..i], &head[i + CRLF.len()..]),
        None => (head, &[][..]),
    };

    // request-line = method SP request-target SP HTTP-version
    let mut parts = request_line.splitn(3, |&b| b == b' ');
    let (Some(method), Some(target), Some(version)) = (parts.next(), parts.next(), parts.next())
    else {
        return reject(StatusCode::BadRequest);
    };
    if method.is_empty() || target.is_empty() {
        return reject(StatusCode::BadRequest);
    }
    if !version.starts_with(b"HTTP/1.") {
        return reject(if version.starts_with(b"HTTP/") {
            StatusCode::HttpVersionNotSupported
        } else {
            StatusCode::BadRequest
        });
    }

    let mut content_length: Option<usize> = None;
    while !rest.is_empty() {
        let line = match find(rest, CRLF) {
            Some(i) => {
                let line = &rest[..i];
                rest = &rest[i + CRLF.len()..];
                line
            }
            None => std::mem::take(&mut rest),
        };

        let Some(colon) = line.iter().position(|&b| b == b':').filter(|&c| c > 0) else {
            return reject(StatusCode::BadRequest);
        };
        let name = &line[..colon];
        let value = trim(&line[colon + 1..]);

        if name.eq_ignore_ascii_case(b"Content-Length") {
            let Some(len) = parse_content_length(value) else {
                return reject(StatusCode::BadRequest);
            };
            if content_length.is_some_and(|prev| prev != len) {
                return reject(StatusCode::BadRequest);
            }
            content_length = Some(len);
        } else if name.eq_ignore_ascii_case(b"Transfer-Encoding") {
            return reject(StatusCode::NotImplemented);
        }
    }

    let length = content_length.unwrap_or(0);
    let already = &buf[header_end + HEADER_END.len()..];
    if length > limits.max_body_bytes {
        if already.len() < length {
            discard(r, length - already.len());
        }
        return reject(StatusCode::ContentTooLarge);
    }

    let mut body = Vec::with_capacity(length);
    body.extend_from_slice(&already[..already.len().min(length)]);
    if body.len() < length {
        let missing = length - body.len();
        match r.take(missing as u64).read_to_end(&mut body) {
            Ok(n) if n == missing => {}
            _ => return ReadOutcome::Disconnected, // truncated body: peer is gone
        }
    }

    ReadOutcome::Request(Request {
        method: String::from_utf8_lossy(method).into_owned(),
        target: String::from_utf8_lossy(target).into_owned(),
        body,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn read(raw: &[u8]) -> ReadOutcome {
        read_request(&mut &raw[..], &Limits::default())
    }

    fn status_of(outcome: ReadOutcome) -> StatusCode {
        match outcome {
            ReadOutcome::Reject(r) => r.status,
            other => panic!("expected rejection, got {other:?}"),
        }
    }

    #[test]
    fn parses_request_with_body() {
        let ReadOutcome::Request(req) =
            read(b"PUT /kv/a HTTP/1.1\r\ncontent-length:  5 \r\n\r\nhelloextra")
        else {
            panic!("expected request");
        };
        assert_eq!(req.method, "PUT");
        assert_eq!(req.target, "/kv/a");
        assert_eq!(req.body, b"hello");
    }

    #[test]
    fn rejects_malformed() {
        assert_eq!(status_of(read(b"GET /\r\n\r\n")), StatusCode::BadRequest);
        assert_eq!(
            status_of(read(b"GET / HTTP/2\r\n\r\n")),
            StatusCode::HttpVersionNotSupported
        );
        assert_eq!(
            status_of(read(b"GET / HTTP/1.1\r\nContent-Length: +1\r\n\r\n")),
            StatusCode::BadRequest
        );
        assert_eq!(
            status_of(read(
                b"GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n"
            )),
            StatusCode::NotImplemented
        );
    }

    #[test]
    fn truncated_body_is_disconnect() {
        assert!(matches!(
            read(b"PUT /kv/a HTTP/1.1\r\nContent-Length: 10\r\n\r\nabc"),
            ReadOutcome::Disconnected
        ));
    }
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.

mod http;
mod router;
mod store;

use std::io;
use std::net::{Ipv4Addr, Shutdown, TcpListener, TcpStream};
use std::panic::{self, AssertUnwindSafe};
use std::process::ExitCode;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use http::{Limits, ReadOutcome, Response, StatusCode};
use router::Router;
use store::KvStore;

/// Don't let an idle or stalled client pin a thread forever.
const IO_TIMEOUT: Duration = Duration::from_secs(30);

fn configure_client(stream: &TcpStream) -> io::Result<()> {
    stream.set_nodelay(true)?;
    stream.set_read_timeout(Some(IO_TIMEOUT))?;
    stream.set_write_timeout(Some(IO_TIMEOUT))
}

fn serve_connection(mut stream: TcpStream, store: &KvStore) {
    if let Err(e) = configure_client(&stream) {
        eprintln!("failed to configure connection: {e}");
        return;
    }

    let response = match http::read_request(&mut stream, &Limits::default()) {
        ReadOutcome::Request(request) => {
            let router = Router::new(store);
            panic::catch_unwind(AssertUnwindSafe(|| router.handle(request)))
                .unwrap_or_else(|_| Response::empty(StatusCode::InternalServerError))
        }
        ReadOutcome::Reject(response) => response,
        ReadOutcome::Disconnected => return,
    };
    // Write failures mean the peer went away; nothing left to do.
    if response.write_to(&mut stream).is_ok() {
        // Half-close so the client reads the full response before the FIN.
        let _ = stream.shutdown(Shutdown::Write);
    }
}

fn is_transient_accept_error(e: &io::Error) -> bool {
    matches!(
        e.kind(),
        io::ErrorKind::Interrupted | io::ErrorKind::ConnectionAborted
    )
}

fn is_fd_exhaustion(e: &io::Error) -> bool {
    matches!(e.raw_os_error(), Some(code) if code == 23 || code == 24) // ENFILE, EMFILE
}

fn run(port: u16) -> io::Result<()> {
    let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, port))?;
    let store = Arc::new(KvStore::new());

    loop {
        let stream = match listener.accept() {
            Ok((stream, _)) => stream,
            Err(e) if is_transient_accept_error(&e) => continue,
            Err(e) if is_fd_exhaustion(&e) => {
                thread::sleep(Duration::from_millis(10));
                continue;
            }
            Err(e) => return Err(e),
        };
        // One thread per connection: connections are short-lived and the
        // required concurrency is modest.
        let store = Arc::clone(&store);
        if let Err(e) = thread::Builder::new()
            .name("conn".into())
            .spawn(move || serve_connection(stream, &store))
        {
            eprintln!("failed to spawn handler: {e}");
        }
    }
}

fn parse_port(s: &str) -> Option<u16> {
    s.parse().ok().filter(|&p| p != 0)
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let [_, port_arg] = args.as_slice() else {
        let prog = args.first().map_or("kvhttp", String::as_str);
        eprintln!("usage: {prog} <port>");
        return ExitCode::from(2);
    };
    let Some(port) = parse_port(port_arg) else {
        eprintln!("invalid port: {port_arg}");
        return ExitCode::from(2);
    };

    match run(port) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("fatal: {e}");
            ExitCode::FAILURE
        }
    }
}

//! Maps requests onto the key/value API described in SPEC.md.

use crate::http::{Body, Request, Response, StatusCode};
use crate::store::KvStore;

const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LEN: usize = 64;

fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn method_not_allowed(allow: &str) -> Response {
    Response::empty(StatusCode::MethodNotAllowed).header("Allow", allow)
}

pub struct Router<'a> {
    store: &'a KvStore,
}

impl<'a> Router<'a> {
    pub fn new(store: &'a KvStore) -> Self {
        Self { store }
    }

    pub fn handle(&self, request: Request) -> Response {
        match request.target.as_str() {
            "/health" if request.method == "GET" => Response::text(StatusCode::Ok, "ok"),
            "/kv" if request.method == "GET" => self.list_keys(),
            "/health" | "/kv" => method_not_allowed("GET"),
            path => match path.strip_prefix(KV_PREFIX) {
                Some(key) if is_valid_key(key) => {
                    self.handle_key(&request.method, key, request.body)
                }
                Some(_) => Response::empty(StatusCode::BadRequest),
                None => Response::empty(StatusCode::NotFound),
            },
        }
    }

    fn handle_key(&self, method: &str, key: &str, body: Vec<u8>) -> Response {
        match method {
            "GET" => match self.store.get(key) {
                Some(value) => Response::with_body(
                    StatusCode::Ok,
                    Body::Shared(value),
                    "application/octet-stream",
                ),
                None => Response::empty(StatusCode::NotFound),
            },
            "PUT" => Response::empty(if self.store.put(key, body) {
                StatusCode::Created
            } else {
                StatusCode::Ok
            }),
            "DELETE" => Response::empty(if self.store.remove(key) {
                StatusCode::NoContent
            } else {
                StatusCode::NotFound
            }),
            _ => method_not_allowed("GET, PUT, DELETE"),
        }
    }

    fn list_keys(&self) -> Response {
        // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
        let keys = self.store.keys();
        let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
        json.push('[');
        for (i, key) in keys.iter().enumerate() {
            if i > 0 {
                json.push(',');
            }
            json.push('"');
            json.push_str(key);
            json.push('"');
        }
        json.push(']');
        Response::with_body(
            StatusCode::Ok,
            Body::Owned(json.into_bytes()),
            "application/json",
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn req(method: &str, target: &str, body: &[u8]) -> Request {
        Request {
            method: method.into(),
            target: target.into(),
            body: body.to_vec(),
        }
    }

    #[test]
    fn routes() {
        let store = KvStore::new();
        let router = Router::new(&store);
        let status = |m: &str, t: &str, b: &[u8]| router.handle(req(m, t, b)).status;

        assert_eq!(status("GET", "/health", b""), StatusCode::Ok);
        assert_eq!(status("POST", "/health", b""), StatusCode::MethodNotAllowed);
        assert_eq!(status("PUT", "/kv/a", b"x"), StatusCode::Created);
        assert_eq!(status("PUT", "/kv/a", b"y"), StatusCode::Ok);
        assert_eq!(status("PATCH", "/kv/a", b""), StatusCode::MethodNotAllowed);
        assert_eq!(status("GET", "/kv/", b""), StatusCode::BadRequest);
        assert_eq!(status("GET", "/kv/a/b", b""), StatusCode::BadRequest);
        assert_eq!(
            status("GET", &format!("/kv/{}", "a".repeat(65)), b""),
            StatusCode::BadRequest
        );
        assert_eq!(status("GET", "/nope", b""), StatusCode::NotFound);
        assert_eq!(status("DELETE", "/kv/a", b""), StatusCode::NoContent);
        assert_eq!(status("DELETE", "/kv/a", b""), StatusCode::NotFound);
    }
}

//! Thread-safe in-memory key/value store.

use std::collections::BTreeMap;
use std::sync::{Arc, PoisonError, RwLock};

/// A stored value. Shared so readers can drop the lock before the
/// (possibly large) value is sent.
pub type Value = Arc<[u8]>;

#[derive(Debug, Default)]
pub struct KvStore {
    map: RwLock<BTreeMap<String, Value>>,
}

impl KvStore {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`. Returns `true` if the key was new,
    /// `false` if it replaced an existing value.
    pub fn put(&self, key: &str, value: Vec<u8>) -> bool {
        let value: Value = value.into();
        let mut map = self.map.write().unwrap_or_else(PoisonError::into_inner);
        if let Some(slot) = map.get_mut(key) {
            *slot = value;
            false
        } else {
            map.insert(key.to_owned(), value);
            true
        }
    }

    pub fn get(&self, key: &str) -> Option<Value> {
        let map = self.map.read().unwrap_or_else(PoisonError::into_inner);
        map.get(key).cloned()
    }

    /// Removes `key`. Returns `true` if it was present.
    pub fn remove(&self, key: &str) -> bool {
        let mut map = self.map.write().unwrap_or_else(PoisonError::into_inner);
        map.remove(key).is_some()
    }

    /// All keys in ascending byte-wise order.
    pub fn keys(&self) -> Vec<String> {
        let map = self.map.read().unwrap_or_else(PoisonError::into_inner);
        map.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_remove() {
        let store = KvStore::new();
        assert!(store.put("a", b"1".to_vec()));
        assert!(!store.put("a", b"2".to_vec()));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.remove("a"));
        assert!(!store.remove("a"));
        assert!(store.get("a").is_none());
    }

    #[test]
    fn keys_sorted() {
        let store = KvStore::new();
        for k in ["b", "a", "C", "_"] {
            store.put(k, Vec::new());
        }
        assert_eq!(store.keys(), ["C", "_", "a", "b"]);
    }
}
